[[nodiscard]] inline bool parse_OrdRejReason(const char *s, OrdRejReason &out) noexcept {
	if (!s) return false;
	if (std::strcmp(s, "0") == 0) { out = OrdRejReason::BROKER; return true; }
	if (std::strcmp(s, "1") == 0) { out = OrdRejReason::UNKNOWN_SYMBOL; return true; }
	if (std::strcmp(s, "2") == 0) { out = OrdRejReason::EXCHANGE_CLOSED; return true; }
	if (std::strcmp(s, "3") == 0) { out = OrdRejReason::ORDER_EXCEEDS_LIMIT; return true; }
	if (std::strcmp(s, "4") == 0) { out = OrdRejReason::TOO_LATE_TO_ENTER; return true; }
	if (std::strcmp(s, "5") == 0) { out = OrdRejReason::UNKNOWN_ORDER; return true; }
	if (std::strcmp(s, "6") == 0) { out = OrdRejReason::DUPLICATE_ORDER; return true; }
	if (std::strcmp(s, "7") == 0) { out = OrdRejReason::DUPLICATE_OF_A_VERBALLY_COMMUNICATED_ORDER; return true; }
	if (std::strcmp(s, "8") == 0) { out = OrdRejReason::STALE_ORDER; return true; }
	if (std::strcmp(s, "9") == 0) { out = OrdRejReason::TRADE_ALONG_REQUIRED; return true; }
	if (std::strcmp(s, "10") == 0) { out = OrdRejReason::INVALID_INVESTOR_ID; return true; }
	if (std::strcmp(s, "11") == 0) { out = OrdRejReason::UNSUPPORTED_ORDER_CHARACTERISTIC12_SURVEILLENCE_OPTION; return true; }
	if (std::strcmp(s, "13") == 0) { out = OrdRejReason::INCORRECT_QUANTITY; return true; }
	if (std::strcmp(s, "14") == 0) { out = OrdRejReason::INCORRECT_ALLOCATED_QUANTITY; return true; }
	if (std::strcmp(s, "15") == 0) { out = OrdRejReason::UNKNOWN_ACCOUNT; return true; }
	if (std::strcmp(s, "99") == 0) { out = OrdRejReason::OTHER; return true; }
	return false;
}

