enum class ScopeBit : uint8_t {
	LOCAL,
	NATIONAL,
	GLOBAL,
};

using ScopeMask = uint64_t;

constexpr ScopeMask bit(ScopeBit b) noexcept { return 1ull << (uint8_t)b; }
constexpr ScopeMask set(ScopeMask m, ScopeBit b) noexcept { return m | bit(b); }
constexpr bool has(ScopeMask m, ScopeBit b) noexcept { return (m & bit(b)) != 0; }

[[nodiscard]] inline bool parse_Scope(const char *s, ScopeMask &out) noexcept {
	out = 0;
	if (!s) return false;
	const char *p = s;
	while (*p) {
		if (*p == ' ') { ++p; continue; }
		switch (*p) {
			case '1': out |= bit(ScopeBit::LOCAL); break;
			case '2': out |= bit(ScopeBit::NATIONAL); break;
			case '3': out |= bit(ScopeBit::GLOBAL); break;
		}
		++p;
	}
	return true;
}

[[nodiscard]] inline const char *to_string_Scope(ScopeMask m, char *buf, std::size_t cap) noexcept {
	std::size_t pos = 0;
	auto append = [&](const char *t){ std::size_t len=std::strlen(t); if(pos+len+1<cap){ std::memcpy(buf+pos,t,len); pos+=len; buf[pos++]=' '; } };
	if (has(m, ScopeBit::LOCAL)) append("1");
	if (has(m, ScopeBit::NATIONAL)) append("2");
	if (has(m, ScopeBit::GLOBAL)) append("3");
	if (pos > 0) buf[pos-1] = '\0'; else if (cap > 0) buf[0] = '\0';
	return buf;
}

